def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def status_priority(status: str) -> int:
        return {"pass": 0, "skip": 1, "fail": 2}.get(status, 0)

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        prev = results.get(name)
        if prev is None or status_priority(status) > status_priority(prev):
            results[name] = status

    def clean_xml(text: str) -> str:
        cleaned = []
        for ch in text:
            code = ord(ch)
            if ch in ("\t", "\n", "\r"):
                cleaned.append(ch)
            elif 0x20 <= code <= 0xD7FF or 0xE000 <= code <= 0xFFFD or 0x10000 <= code <= 0x10FFFF:
                cleaned.append(ch)
            # else drop invalid XML char
        return "".join(cleaned)

    def parse_testsuite(ts_root: ET.Element) -> None:
        for tc in ts_root.findall(".//testcase"):
            name = tc.get("name") or tc.get("classname") or ""
            status = "pass"
            status_attr = (tc.get("status") or "").lower()
            result_attr = (tc.get("result") or "").lower()
            if tc.find("skipped") is not None or status_attr in {"skipped", "notrun", "skip"} or result_attr == "skipped":
                status = "skip"
            if tc.find("failure") is not None or tc.find("error") is not None or status_attr in {"fail", "failed", "error"} or result_attr in {"fail", "failed", "error"}:
                status = "fail"
            add_result(name, status)

    cleaned = clean_xml(log)

    parsed_any = False
    try:
        root = ET.fromstring(cleaned)
        parsed_any = True
        if root.tag == "testsuites":
            for ts in root.findall("testsuite"):
                parse_testsuite(ts)
        elif root.tag == "testsuite":
            parse_testsuite(root)
        else:
            for ts in root.findall(".//testsuite"):
                parse_testsuite(ts)
    except ET.ParseError:
        parsed_any = False

    if not parsed_any:
        # Try extracting all <testsuite> blocks.
        for match in re.finditer(r"<testsuite\b[^>]*>.*?</testsuite>", cleaned, re.DOTALL):
            block = match.group(0)
            try:
                ts_root = ET.fromstring(block)
            except ET.ParseError:
                continue
            parse_testsuite(ts_root)

    # Fallback to common non-XML patterns if still empty.
    if not results:
        # pytest: file.py::test_name PASSED/FAILED/SKIPPED/ERROR
        for m in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", log, re.MULTILINE):
            name, raw_status = m.group(1), m.group(2)
            status = {"PASSED": "pass", "FAILED": "fail", "ERROR": "fail", "SKIPPED": "skip"}[raw_status]
            add_result(name, status)

        # unittest: TestClass.test_method ... ok/FAIL/ERROR/skipped
        for m in re.finditer(r"^(\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", log, re.MULTILINE):
            name, raw_status = m.group(1), m.group(2)
            if raw_status == "ok":
                status = "pass"
            elif raw_status == "skipped":
                status = "skip"
            else:
                status = "fail"
            add_result(name, status)

        # Go test: --- PASS/FAIL/SKIP: TestName
        for m in re.finditer(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", log, re.MULTILINE):
            raw_status, name = m.group(1), m.group(2)
            status = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}[raw_status]
            add_result(name, status)

        # Jest: ✓ name or ✕ name or ○ name
        for m in re.finditer(r"^(✓|✕|○)\s+(.+)$", log, re.MULTILINE):
            symbol, name = m.group(1), m.group(2).strip()
            status = {"✓": "pass", "✕": "fail", "○": "skip"}[symbol]
            add_result(name, status)

    return results
